Read text file `core/uploads.ts`.
1|// Pure upload contract: limits, ids, strict parsing, word counts, part
2|// splitting, key builders, error codes. No env reads, no network, no
3|// secrets. Server modules in server/uploads/ build on it.
4|import type { RawSection } from "./clean-types";
5|import { FREE_BOOK_MAX_WORDS } from "./upload-policy";
6|
7|export { FREE_BOOK_MAX_WORDS };
8|
9|// BYOK books pay with the reader's key, so the ceiling is the 4 MB body.
10|export const BYOK_BOOK_MAX_WORDS = 400_000;
11|// Under the Hobby 4.5 MB request limit with JSON overhead to spare.
12|export const UPLOAD_MAX_BODY_BYTES = 4_000_000;
13|export const UPLOAD_STEP_BODY_BYTES = 4096;
14|export const UPLOAD_MAX_SECTIONS = 600;
15|export const UPLOAD_MAX_BLOCKS_PER_SECTION = 2000;
16|export const UPLOAD_MAX_BLOCK_CHARS = 20_000;
17|export const UPLOAD_MAX_TITLE_CHARS = 300;
18|export const UPLOAD_MAX_CHAPTERS = 500;
19|// One part fits one segment call plus its scenes inside the route budget.
20|export const UPLOAD_MAX_PART_PARAGRAPHS = 150;
21|// Global free-upload spend: USD 1 per UTC day, shared across readers.
22|export const UPLOAD_DAILY_SPEND_CAP_MICRO = 1_000_000;
23|// Flat reserve per free book; the real cost reconciles at finalize.
24|export const UPLOAD_RESERVE_MICRO = 250_000;
25|export const UPLOAD_TTL_DAYS = 30;
26|export const UPLOAD_JOB_TTL_SEC = 30 * 24 * 3600;
27|export const UPLOAD_MODEL = "muse-spark-1.3-contributor";
28|export const UPLOAD_JEV_MODEL = "jev-1.14.0";
29|
30|export type UploadErrorCode =
31|  | "too_long"
32|  | "daily_books_reached"
33|  | "daily_budget_reached"
34|  | "human_required"
35|  | "bad_request"
36|  | "unavailable"
37|  | "not_found"
38|  | "expired";
39|
40|export const UPLOAD_MESSAGES: Record<UploadErrorCode, string> = {
41|  too_long: "This one is longer than the free book covers. With your own Meta key you can still read it with a soundtrack.",
42|  daily_books_reached: "That's two free books for today. More tomorrow, or use your own key for this one.",
43|  daily_budget_reached: "So many people loved this that we've run out of credits to share today. Try again tomorrow, or bring your own key.",
44|  human_required: "One quick check that you're a person first.",
45|  bad_request: "Something went wrong there. Try again?",
46|  unavailable: "We couldn't process this book right now. Try again in a moment.",
47|  not_found: "We couldn't find this upload. It may have expired.",
48|  expired: "This upload expired after 30 days. Upload the book again to read it.",
49|};
50|
51|export const UPLOAD_HTTP_STATUS: Record<UploadErrorCode, number> = {
52|  too_long: 413,
53|  daily_books_reached: 429,
54|  daily_budget_reached: 503,
55|  human_required: 403,
56|  bad_request: 400,
57|  unavailable: 503,
58|  not_found: 404,
59|  expired: 410,
60|};
61|
62|export class UploadValidationError extends Error {
63|  constructor(message = "invalid upload request") {
64|    super(message);
65|    this.name = "UploadValidationError";
66|  }
67|}
68|
69|// 128-bit random, base64url without padding (22 chars), prefixed so ids
70|// never collide with paragraph or scene ids.
71|export const UPLOAD_ID_RE = /^u-[A-Za-z0-9_-]{22}$/;
72|
73|const B64URL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
74|
75|export function newUploadId(): string {
76|  const bytes = new Uint8Array(16);
77|  globalThis.crypto.getRandomValues(bytes);
78|  let out = "u-";
79|  let bits = 0;
80|  let value = 0;
81|  for (const byte of bytes) {
82|    value = (value << 8) | byte;
83|    bits += 8;
84|    while (bits >= 6) {
85|      bits -= 6;
86|      out += B64URL[(value >> bits) & 63];
87|    }
88|  }
89|  if (bits > 0) out += B64URL[(value << (6 - bits)) & 63];
90|  return out;
91|}
92|
93|export function isUploadId(id: unknown): id is string {
94|  return typeof id === "string" && UPLOAD_ID_RE.test(id);
95|}
96|
97|export function parseUploadId(id: unknown): string {
98|  if (!isUploadId(id)) throw new UploadValidationError("bad upload id");
99|  return id;
100|}
101|
102|export interface UploadCreateBody {
103|  title: string;
104|  author: string | null;
105|  sections: RawSection[];
106|  turnstileToken?: string;
107|}
108|
109|function isRecord(json: unknown): json is Record<string, unknown> {
110|  return typeof json === "object" && json !== null && !Array.isArray(json);
111|}
112|
113|function isStringArray(value: unknown, maxItems: number, maxChars: number): value is string[] {
114|  return (
115|    Array.isArray(value) &&
116|    value.length <= maxItems &&
117|    value.every((t) => typeof t === "string" && t.length <= maxChars)
118|  );
119|}
120|
121|// Strict parse at the trust boundary: exact fields only, defensive caps on
122|// every list and string, so a bad client cannot push unbounded work in.
123|export function parseUploadCreate(json: unknown): UploadCreateBody {
124|  if (!isRecord(json)) throw new UploadValidationError();
125|  const keys = Object.keys(json).sort().join(",");
126|  const base = "author,sections,title";
127|  if (keys !== base && keys !== "sections,title" && keys !== `${base},turnstileToken` && keys !== "sections,title,turnstileToken") {
128|    throw new UploadValidationError();
129|  }
130|  const title = json.title;
131|  if (typeof title !== "string" || title.trim().length === 0 || title.length > UPLOAD_MAX_TITLE_CHARS) {
132|    throw new UploadValidationError();
133|  }
134|  const author = json.author;
135|  if (author !== undefined && author !== null && (typeof author !== "string" || author.length > UPLOAD_MAX_TITLE_CHARS)) {
136|    throw new UploadValidationError();
137|  }
138|  const sections = json.sections;
139|  if (!Array.isArray(sections) || sections.length === 0 || sections.length > UPLOAD_MAX_SECTIONS) {
140|    throw new UploadValidationError();
141|  }
142|  const parsed: RawSection[] = sections.map((sec) => {
143|    if (!isRecord(sec)) throw new UploadValidationError();
144|    if (Object.keys(sec).sort().join(",") !== "blocks,docTitle,href,id,linear,navLabel,types") {
145|      throw new UploadValidationError();
146|    }
147|    if (typeof sec.id !== "string" || sec.id.length === 0 || sec.id.length > UPLOAD_MAX_TITLE_CHARS) {
148|      throw new UploadValidationError();
149|    }
150|    if (typeof sec.href !== "string" || sec.href.length > 2000) throw new UploadValidationError();
151|    if (typeof sec.linear !== "boolean") throw new UploadValidationError();
152|    if (!isStringArray(sec.types, 20, 100)) throw new UploadValidationError();
153|    for (const key of ["docTitle", "navLabel"] as const) {
154|      const value = sec[key];
155|      if (value !== null && (typeof value !== "string" || value.length > UPLOAD_MAX_TITLE_CHARS)) {
156|        throw new UploadValidationError();
157|      }
158|    }
159|    if (!Array.isArray(sec.blocks) || sec.blocks.length > UPLOAD_MAX_BLOCKS_PER_SECTION) {
160|      throw new UploadValidationError();
161|    }
162|    const blocks = sec.blocks.map((block) => {
163|      if (!isRecord(block)) throw new UploadValidationError();
164|      if (Object.keys(block).sort().join(",") !== "heading,text") throw new UploadValidationError();
165|      if (typeof block.text !== "string" || block.text.length > UPLOAD_MAX_BLOCK_CHARS) {
166|        throw new UploadValidationError();
167|      }
168|      if (typeof block.heading !== "boolean") throw new UploadValidationError();
169|      return { text: block.text, heading: block.heading };
170|    });
171|    return {
172|      id: sec.id,
173|      href: sec.href,
174|      linear: sec.linear,
175|      types: sec.types as string[],
176|      docTitle: sec.docTitle as string | null,
177|      navLabel: sec.navLabel as string | null,
178|      blocks,
179|    };
180|  });
181|  const out: UploadCreateBody = {
182|    title: title.trim(),
183|    author: typeof author === "string" && author.trim() !== "" ? author.trim() : null,
184|    sections: parsed,
185|  };
186|  if (json.turnstileToken !== undefined) {
187|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
188|      throw new UploadValidationError();
189|    }
190|    out.turnstileToken = json.turnstileToken;
191|  }
192|  return out;
193|}
194|
195|// Same word shape the browser counts for routing, so the server enforces
196|// the limit the client promised.
197|const WORD_RE = /[\p{L}\p{N}]+(?:['’][\p{L}]+)*/gu;
198|
199|export function countWords(text: string): number {
200|  WORD_RE.lastIndex = 0;
201|  let count = 0;
202|  let match: RegExpExecArray | null;
203|  while ((match = WORD_RE.exec(text)) !== null && match[0].length > 0) count += 1;
204|  return count;
205|}
206|
207|export function countChapterWords(chapters: { paragraphs: string[] }[]): number {
208|  let total = 0;
209|  for (const chapter of chapters) {
210|    for (const paragraph of chapter.paragraphs) total += countWords(paragraph);
211|  }
212|  return total;
213|}
214|
215|export interface UploadPart {
216|  ch: number;
217|  part: number;
218|  startN: number;
219|  endN: number;
220|}
221|
222|export function partKey(part: Pick<UploadPart, "ch" | "part">): string {
223|  return `ch${part.ch}p${part.part}`;
224|}
225|
226|// Long chapters split into paragraph windows so one step stays in budget.
227|export function splitChapterParts(
228|  chapters: { ch: number; start_n: number; end_n: number }[],
229|  maxParas: number = UPLOAD_MAX_PART_PARAGRAPHS,
230|): UploadPart[] {
231|  const parts: UploadPart[] = [];
232|  for (const chapter of chapters) {
233|    let part = 1;
234|    for (let start = chapter.start_n; start <= chapter.end_n; start += maxParas, part += 1) {
235|      parts.push({ ch: chapter.ch, part, startN: start, endN: Math.min(start + maxParas - 1, chapter.end_n) });
236|    }
237|  }
238|  return parts;
239|}
240|
241|export function parseStepBody(json: unknown): { chapter?: number; turnstileToken?: string } {
242|  if (!isRecord(json)) throw new UploadValidationError();
243|  const keys = Object.keys(json).sort().join(",");
244|  if (keys !== "" && keys !== "chapter" && keys !== "turnstileToken" && keys !== "chapter,turnstileToken") {
245|    throw new UploadValidationError();
246|  }
247|  const out: { chapter?: number; turnstileToken?: string } = {};
248|  if (json.chapter !== undefined) {
249|    if (typeof json.chapter !== "number" || !Number.isSafeInteger(json.chapter) || json.chapter < 1) {
250|      throw new UploadValidationError();
251|    }
252|    out.chapter = json.chapter;
253|  }
254|  if (json.turnstileToken !== undefined) {
255|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
256|      throw new UploadValidationError();
257|    }
258|    out.turnstileToken = json.turnstileToken;
259|  }
260|  return out;
261|}
262|
263|// Private Blob layout; the id is unguessable, URLs never leave the server.
264|export function uploadBookPath(id: string): string {
265|  return `uploads/${id}/book.json`;
266|}
267|
268|export function uploadPartPath(id: string, part: string): string {
269|  return `uploads/${id}/part-${part}.json`;
270|}
271|
272|export function uploadAnalysisPath(id: string): string {
273|  return `uploads/${id}/analysis.json`;
274|}
275|
276|export function uploadDailySpendKey(day: string): string {
277|  return `upload:spend:daily:${day}`;
278|}

