25|function matchesBearer(auth: string, secret: string): boolean {
26|  const expected = `Bearer ${secret}`;
27|  if (auth.length !== expected.length) return false;
28|  return timingSafeEqual(Buffer.from(auth), Buffer.from(expected));
29|}
30|
31|// Vercel cron calls this daily with CRON_SECRET as the Bearer [REDACTED] Any
32|// auth failure answers 404 so the route stays hidden.
33|export async function handleCleanup(
34|  req: Request,
35|  deps: { store?: UploadStore; secret?: string; token?: string } = {},
36|): Promise<Response> {
37|  const secret = deps.secret ?? usable(process.env.CRON_SECRET);
38|  if (!secret || !matchesBearer(req.headers.get("authorization") ?? "", secret)) {
39|    return Response.json({ status: "error", code: "not_found" }, { status: 404 });
40|  }
41|  // Same private store as the routes; never the public image store.
42|  const token = deps.token ?? usable(process.env.UPLOADS_BLOB_READ_WRITE_TOKEN);
43|  if (!deps.store && !token) {
44|    console.warn("upload cleanup unavailable");
45|    return Response.json({ status: "error", code: "unavailable" }, { status: 503 });
46|  }
47|  try {
48|    const out = await cleanupUploads(deps.store ?? createUploadStore(token as string));
49|    return Response.json({ status: "ok", deleted: out.deleted });
50|  } catch {
51|    console.error("upload cleanup failed");
52|    return Response.json({ status: "error", code: "unavailable" }, { status: 503 });
53|  }
