33|export interface StepArgs {
34|  kv: KV;
35|  store: UploadStore;
36|  meta: MetaClient;
37|  jev: JevClient | null;
38|  id: string;
39|  chapter?: number;
40|}
41|
42|export type StepResult =
43|  | { status: "working"; id: string; done: number; total: number }
44|  | { status: "done"; id: string; done: number; total: number; costUsd: number };
45|
46|interface StoredPart {
47|  part: string;
48|  ch: number;
49|  scenes: (SceneInput & SceneEmotion & { ch: number })[];
50|}
51|
52|function parseStoredPart(raw: string): StoredPart | null {
53|  let json: unknown;
54|  try {
55|    json = JSON.parse(raw);
56|  } catch {
57|    return null;
58|  }
59|  if (typeof json !== "object" || json === null) return null;
60|  const p = json as Record<string, unknown>;
61|  if (typeof p.part !== "string" || typeof p.ch !== "number" || !Array.isArray(p.scenes)) return null;
62|  for (const s of p.scenes) {
63|    if (typeof s !== "object" || s === null) return null;
64|    const scene = s as Record<string, unknown>;
65|    if (typeof scene.start_n !== "number" || typeof scene.end_n !== "number") return null;
66|    if (typeof scene.title !== "string" || typeof scene.summary !== "string") return null;
67|    if (!Array.isArray(scene.characters)) return null;
68|  }
69|  return json as StoredPart;
70|}
71|
72|function parseUploadBook(raw: string | null, job: UploadJob): UploadBook | null {
73|  if (raw === null) return null;
74|  let json: unknown;
75|  try {
76|    json = JSON.parse(raw);
77|  } catch {
78|    return null;
79|  }
80|  if (typeof json !== "object" || json === null) return null;
81|  const book = json as Partial<UploadBook>;
82|  if (book.id !== job.id || book.textVersion !== job.textVersion) return null;
83|  if (!Array.isArray(book.chapters) || !Array.isArray(book.paragraphs)) return null;
84|  return json as UploadBook;
85|}
86|
87|function workingResult(job: UploadJob): StepResult {
88|  return { status: "working", id: job.id, done: job.doneParts.length, total: job.parts.length };
89|}
90|
91|function doneResult(job: UploadJob): StepResult {
92|  return {
93|    status: "done",
94|    id: job.id,
95|    done: job.parts.length,
96|    total: job.parts.length,
97|    costUsd: job.costMicro !== null ? job.costMicro / 1_000_000 : usageCostUsd(job.usage),
98|  };
99|}
100|
101|// Marks the job failed and refunds quota plus the spend reserve exactly
102|// once per job, via a setNxEx guard. Best effort throughout: when Redis
103|// itself is down the reservation is kept, which is the conservative side.
104|// A job already done is never refunded.
105|async function failJob(kv: KV, job: UploadJob): Promise<void> {
106|  if (job.status === "done") return;
107|  job.status = "failed";
108|  try {
109|    await saveUploadJob(kv, job);
110|  } catch {
111|    // The refund guard below still bounds us to one refund.
112|  }
113|  let first = false;
114|  try {
115|    first = await kv.setNxEx(uploadRefundKey(job.id), "1", UPLOAD_JOB_TTL_SEC);
116|  } catch {
117|    return;
118|  }
119|  if (!first) return;
120|  if (job.quotaIp && job.quotaAnon) await refundDualQuota(kv, { ip: job.quotaIp, anon: job.quotaAnon });
121|  if (job.reservedMicro > 0) {
122|    try {
123|      await kv.decrBy(spendKey(), job.reservedMicro);
124|      await kv.decrBy(uploadDailySpendKey(job.day), job.reservedMicro);
125|    } catch {
126|      // Kept on Redis failure: conservative, like an abandoned job.
127|    }
128|  }
129|}
130|
131|async function markDoneAndMaybeFinalize(args: StepArgs, job: UploadJob, part: string): Promise<StepResult> {
132|  if (!job.doneParts.includes(part)) job.doneParts.push(part);
133|  await saveUploadJob(args.kv, job);
134|  if (job.doneParts.length < job.parts.length) return workingResult(job);
135|  return finalize(args, job);
136|}
137|
138|// Assembles the analysis once, under a guard: concurrent last-part drivers
139|// converge on the winner's result, and a finalize that died between the
140|// blob write and the job save repairs from the blob on retry.
141|async function finalize(args: StepArgs, job: UploadJob): Promise<StepResult> {
142|  const first = await args.kv.setNxEx(uploadFinalizeKey(job.id), "1", UPLOAD_JOB_TTL_SEC);
143|  if (!first) {
144|    const fresh = await loadUploadJob(args.kv, job.id);
145|    if (!fresh) throw new UploadFailure("not_found");
146|    if (fresh.status === "done") return doneResult(fresh);
147|    if (fresh.status === "failed") throw new UploadFailure("unavailable");
148|    const analysis = await args.store.readText(uploadAnalysisPath(job.id));
149|    if (analysis) {
150|      fresh.status = "done";
151|      fresh.costMicro = usageCostMicro(fresh.usage);
152|      await saveUploadJob(args.kv, fresh);
153|      return doneResult(fresh);
154|    }
155|    return workingResult(fresh);
156|  }
157|  const scenes: AnalyzedScene[] = [];
158|  for (const chapter of [...job.chapters].sort((a, b) => a.ch - b.ch)) {
159|    const chParts = job.parts.filter((p) => p.ch === chapter.ch).sort((a, b) => a.part - b.part);
160|    let k = 0;
161|    for (const p of chParts) {
162|      const stored = parseStoredPart(await args.store.readText(uploadPartPath(job.id, partKey(p))) ?? "");
163|      if (!stored) throw new WorkError("store");
164|      for (const s of stored.scenes) {
165|        k += 1;
166|        scenes.push({ ...s, id: `c${chapter.ch}s${k}`, ch: chapter.ch });
167|      }
168|    }
169|  }
170|  const book = parseUploadBook(await args.store.readText(uploadBookPath(job.id)), job);
171|  if (!book) throw new WorkError("store");
172|  const problems = validateBookCoverage(book, scenes);
173|  if (problems.length > 0) throw new WorkError("segment");
174|  await args.store.saveJson(uploadAnalysisPath(job.id), JSON.stringify({ bookId: job.id, textVersion: job.textVersion, scenes }));
175|  if (job.path === "free" && job.reservedMicro > 0) {
176|    const delta = usageCostMicro(job.usage) - job.reservedMicro;
177|    if (delta !== 0) {
178|      try {
179|        await args.kv.incrBy(spendKey(), delta);
180|        await args.kv.incrBy(uploadDailySpendKey(job.day), delta);
181|      } catch {
182|        // Best effort: the reserve already bounds the spend.
183|      }
184|    }
185|  }
186|  job.status = "done";
187|  job.costMicro = usageCostMicro(job.usage);
188|  await saveUploadJob(args.kv, job);
189|  return doneResult(job);
190|}
191|
192|// One idempotent unit of work: re-calling a finished part or a finished
193|// job costs nothing. Any throw after the guards fails the job with the
194|// once-guarded refund above, and the client sees only `unavailable`.
195|export async function stepUpload(args: StepArgs): Promise<StepResult> {
196|  const job = await loadUploadJob(args.kv, args.id);
197|  if (!job) throw new UploadFailure("not_found");
198|  if (Date.now() - job.createdAt > UPLOAD_TTL_DAYS * 24 * 3600 * 1000) throw new UploadFailure("expired");
199|  if (job.status === "failed") throw new UploadFailure("unavailable");
200|  if (job.status === "done") return doneResult(job);
201|
202|  const pending = job.parts.filter((p) => !job.doneParts.includes(partKey(p)));
203|  if (args.chapter !== undefined && !job.chapters.some((c) => c.ch === args.chapter)) {
204|    throw new UploadFailure("bad_request");
205|  }
206|  const wanted = args.chapter === undefined ? pending : pending.filter((p) => p.ch === args.chapter);
207|  if (wanted.length === 0) {
208|    if (pending.length > 0) return workingResult(job);
209|    try {
210|      return await finalize(args, job);
211|    } catch (e) {
212|      if (e instanceof UploadFailure) throw e;
213|      await failJob(args.kv, job);
214|      throw new UploadFailure("unavailable");
215|    }
216|  }
217|  const part = wanted[0] as (typeof wanted)[number];
218|  const key = partKey(part);
219|  const path = uploadPartPath(job.id, key);
220|  if (parseStoredPart((await args.store.readText(path)) ?? "")) {
221|    return markDoneAndMaybeFinalize(args, job, key);
222|  }
223|
224|  const lock = uploadLockKey(job.id, key);
225|  const token = randomUUID();
226|  if (!(await args.kv.setNxEx(lock, token, UPLOAD_LOCK_TTL_SEC))) return workingResult(job);
227|  try {
228|    if (parseStoredPart((await args.store.readText(path)) ?? "")) {
229|      return markDoneAndMaybeFinalize(args, job, key);
230|    }
231|    const book = parseUploadBook(await args.store.readText(uploadBookPath(job.id)), job);
232|    if (!book) throw new WorkError("store");
233|    const chapter = job.chapters.find((c) => c.ch === part.ch);
234|    if (!chapter) throw new WorkError("store");
235|    const paras = book.paragraphs
236|      .filter((p) => p.n >= part.startN && p.n <= part.endN)
237|      .map((p) => ({ n: p.n, text: p.text }));
238|    const inputs = await segmentPart(
239|      args.meta,
240|      { ch: chapter.ch, title: chapter.title, start_n: part.startN, end_n: part.endN },
241|      paras,
242|      job.usage,
243|    );
244|    const scenes = inputs.map((s, k) => ({ ...s, id: `w-${key}-${k}`, ch: part.ch }));
245|    const texts = scenes.map((s) =>
246|      paras
247|        .filter((p) => p.n >= s.start_n && p.n <= s.end_n)
248|        .map((p) => p.text)
249|        .join("\n"),
250|    );
251|    const emotions = await classifyPart(
252|      scenes,
253|      texts,
254|      { bookTitle: job.title, chapterTitle: chapter.title },
255|      { meta: args.meta, jev: args.jev },
256|      job.usage,
257|    );
258|    const stored: StoredPart = {
259|      part: key,
260|      ch: part.ch,
261|      scenes: scenes.map((s, i) => ({
262|        start_n: s.start_n,
263|        end_n: s.end_n,
264|        title: s.title,
265|        summary: s.summary,
266|        characters: s.characters,
267|        ch: s.ch,
268|        ...(emotions[i] as SceneEmotion),
269|      })),
270|    };
271|    await args.store.saveJson(path, JSON.stringify(stored));
272|    return await markDoneAndMaybeFinalize(args, job, key);
273|  } catch (e) {
274|    if (e instanceof UploadFailure) throw e;
275|    await failJob(args.kv, job);
276|    throw new UploadFailure("unavailable");
277|  } finally {
278|    try {
279|      await args.kv.releaseIfToken(lock, token);
280|    } catch {
281|      // The TTL frees a lock the route kill left behind.
282|    }
283|  }
284|}

