33|
34|export interface UploadBook {
35|  id: string;
36|  title: string;
37|  author: string;
38|  chapters: Chapter[];
39|  paragraphs: Paragraph[];
40|  textVersion: string;
41|}
42|
43|// Same ordinals and hash input as the Gutenberg path, without the
44|// Gutenberg source block: uploads are reader books, not shelf books.
45|export function buildUploadBook(
46|  id: string,
47|  title: string,
48|  author: string | null,
49|  drafts: { title: string; paragraphs: string[] }[],
50|): UploadBook {
51|  const chapters: Chapter[] = [];
52|  const paragraphs: Paragraph[] = [];
53|  let n = 0;
54|  drafts.forEach((draft, index) => {
55|    const ch = index + 1;
56|    const start_n = n + 1;
57|    draft.paragraphs.forEach((text, k) => {
58|      n += 1;
59|      paragraphs.push({ id: paragraphId(ch, k + 1), ch, n, text });
60|    });
61|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
62|  });
63|  const textVersion = `sha256:${createHash("sha256").update(canonicalLines(paragraphs)).digest("hex")}`;
64|  // The reader prints the author, so a missing one becomes Unknown here.
65|  return { id, title, author: author ?? "Unknown", chapters, paragraphs, textVersion };
66|}
67|
68|export interface CreateArgs {
69|  kv: KV;
70|  store: UploadStore;
71|  meta: MetaClient;
72|  body: UploadCreateBody;
73|  path: "free" | "byok";
74|  anonId: string;
75|  day: string;
76|  quotaKeys: { ip: string; anon: string } | null;
77|  spendCapMicro: number;
78|  judgeBudgetMs?: number;
79|}
80|
81|// Total wall clock the cleaning judge may take inside the create request.
82|// The per-call timeout still applies beneath; retries that outlast this
83|// just lose, and the book keeps its deterministic chapters.
84|export const CLEAN_JUDGE_BUDGET_MS = 25_000;
85|
86|function judgeWithBudget(judge: Judge, ms: number): Judge {
87|  return async (input) => {
88|    let timer: ReturnType<typeof setTimeout> | undefined;
89|    const expired = new Promise<null>((resolve) => {
90|      timer = setTimeout(() => resolve(null), ms);
91|    });
92|    try {
93|      return await Promise.race([judge(input), expired]);
94|    } finally {
95|      if (timer !== undefined) clearTimeout(timer);
96|    }
97|  };
98|}
99|
100|// Validate on the cleaned text first so user errors never take quota;
101|// the judge runs after the spend reserve, and its failure just keeps the
102|// deterministic chapters. Any throw after the reserve refunds everything.
103|export async function createUpload(args: CreateArgs): Promise<{ id: string; chapters: number; parts: number }> {
104|  const preview = cleanDeterministic(args.body.title, args.body.sections);
105|  if (preview.chapters.length === 0 || preview.chapters.length > UPLOAD_MAX_CHAPTERS) {
106|    throw new UploadFailure("bad_request");
107|  }
108|  const limit = args.path === "free" ? FREE_BOOK_MAX_WORDS : BYOK_BOOK_MAX_WORDS;
109|  if (countChapterWords(preview.chapters) > limit) throw new UploadFailure("too_long");
110|
111|  let quotaTaken = false;
112|  let reservation: SpendReservation | null = null;
113|  try {
114|    if (args.path === "free" && args.quotaKeys) {
115|      const taken = await takeDualQuota(args.kv, args.quotaKeys, {
116|        limit: FREE_BOOKS_PER_PERSON,
117|        ttlSec: BOOK_QUOTA_TTL_SEC,
118|      });
119|      if (!taken.ok) throw new UploadFailure("daily_books_reached");
120|      quotaTaken = true;
121|      const spent = await reserveSpend(args.kv, {
122|        amountMicro: UPLOAD_RESERVE_MICRO,
123|        day: args.day,
124|        spendCapMicro: args.spendCapMicro,
125|        dailySpendCapMicro: UPLOAD_DAILY_SPEND_CAP_MICRO,
126|        dailyKey: uploadDailySpendKey(args.day),
127|      });
128|      if (!spent.ok) throw new UploadFailure("daily_budget_reached");
129|      reservation = spent.reservation;
130|    }
131|
132|    const usage = emptyUsage();
133|    const judge = judgeWithBudget(createCleanJudge(args.meta), args.judgeBudgetMs ?? CLEAN_JUDGE_BUDGET_MS);
134|    const cleaned = await cleanSections(args.body.title, args.body.sections, judge);
135|    const llm = cleaned.report.llm;
136|    if (llm && llm.model !== "unknown") {
137|      usage.metaRequests += 1;
138|      usage.metaPrompt += llm.promptTokens;
139|      usage.metaCached += llm.cachedTokens;
140|      usage.metaCompletion += llm.completionTokens;
141|    }
142|    if (cleaned.chapters.length === 0) throw new UploadFailure("bad_request");
143|
144|    const id = newUploadId();
145|    const book = buildUploadBook(id, args.body.title, args.body.author, cleaned.chapters);
146|    const parts = splitChapterParts(book.chapters);
147|    const job: UploadJob = {
148|      v: 1,
149|      id,
150|      path: args.path,
151|      anonId: args.path === "free" ? args.anonId : null,
152|      day: args.day,
153|      createdAt: Date.now(),
154|      title: book.title,
155|      author: book.author,
156|      textVersion: book.textVersion,
157|      chapters: book.chapters.map((c) => ({ ch: c.ch, title: c.title, start_n: c.start_n, end_n: c.end_n })),
158|      parts,
159|      doneParts: [],
160|      status: "working",
161|      usage,
162|      reservedMicro: args.path === "free" ? UPLOAD_RESERVE_MICRO : 0,
163|      quotaIp: args.path === "free" && args.quotaKeys ? args.quotaKeys.ip : null,
164|      quotaAnon: args.path === "free" && args.quotaKeys ? args.quotaKeys.anon : null,
165|      costMicro: null,
166|    };
167|    await args.store.saveJson(uploadBookPath(id), JSON.stringify(book));
168|    await saveUploadJob(args.kv, job);
169|    return { id, chapters: book.chapters.length, parts: parts.length };
170|  } catch (e) {
171|    // Both refunds are best effort and never throw, so the original error
172|    // always survives. A Blob orphan here ages out via the cleanup cron.
173|    await reservation?.release();
174|    if (quotaTaken && args.quotaKeys) await refundDualQuota(args.kv, args.quotaKeys);
175|    if (e instanceof UploadFailure) throw e;
176|    throw new UploadFailure("unavailable");
177|  }
