6|}
7|
8|// Daily spend counter for our key. The day is the UTC day string
9|// YYYY-MM-DD the caller already uses for quota keys, so the daily
10|// cap resets on UTC rollover together with per-person quota.
11|export const DAILY_SPEND_TTL_SEC = 48 * 3600;
12|
13|export function dailySpendKey(day: string): string {
14|  return `img:spend:daily:${day}`;
15|}
16|
17|export function budgetExceeded(totalAfterReserve: number, capMicro: number): boolean {
18|  return totalAfterReserve > capMicro;
19|}
20|
21|export interface SpendReservation {
22|  amountMicro: number;
23|  day: string;
24|  // Gives back each counter at most once: a flag clears only after
25|  // its write lands. Best effort, never throws.
26|  release(): Promise<void>;
27|  // Post-stream reconciliation: folds the real cost into both counters.
28|  // Best effort, never throws.
29|  adjust(deltaMicro: number): Promise<void>;
30|}
31|
32|export interface ReserveSpendArgs {
33|  amountMicro: number;
34|  day: string;
35|  spendCapMicro: number;
36|  dailySpendCapMicro: number;
37|  // Overrides the daily counter key (uploads keep their own daily cap);
38|  // the total key is always shared. Absent means the image/chat key.
39|  dailyKey?: string;
40|}
41|
42|// One reserve for both caps: total first with an expiry refresh on the
43|// daily counter, refunding what was taken on over-cap. A Redis failure
44|// between reserves refunds the total, then rethrows for the caller to
45|// map to unavailable. Only over-cap returns ok: false.
46|export async function reserveSpend(
47|  kv: KV,
48|  args: ReserveSpendArgs,
49|): Promise<{ ok: true; reservation: SpendReservation } | { ok: false; which: "total" | "daily" }> {
50|  const totalKey = spendKey();
51|  const dayKey = args.dailyKey ?? dailySpendKey(args.day);
52|  let totalLeft = false;
53|  let dailyLeft = false;
54|  const releaseTotal = async (): Promise<void> => {
55|    try {
56|      if (totalLeft) {
57|        await kv.decrBy(totalKey, args.amountMicro);
58|        totalLeft = false;
59|      }
60|    } catch {
61|      // Redis down: nothing reserved server-side to retry against.
62|    }
63|  };
64|  const releaseDaily = async (): Promise<void> => {
65|    try {
66|      if (dailyLeft) {
67|        await kv.decrBy(dayKey, args.amountMicro);
68|        dailyLeft = false;
69|      }
70|    } catch {
71|      // Redis down: nothing reserved server-side to retry against.
72|    }
73|  };
74|
75|  const total = await kv.incrBy(totalKey, args.amountMicro);
76|  totalLeft = true;
77|  if (budgetExceeded(total, args.spendCapMicro)) {
78|    await releaseTotal();
79|    return { ok: false, which: "total" };
80|  }
81|
82|  let dailyTotal: number;
83|  try {
84|    dailyTotal = await kv.incrBy(dayKey, args.amountMicro);
85|    dailyLeft = true;
86|    await kv.expire(dayKey, DAILY_SPEND_TTL_SEC);
87|  } catch (e) {
88|    // A Redis failure between reserves must give back what was taken.
89|    await releaseDaily();
90|    await releaseTotal();
91|    throw e;
92|  }
93|  if (budgetExceeded(dailyTotal, args.dailySpendCapMicro)) {
94|    await releaseDaily();
95|    await releaseTotal();
96|    return { ok: false, which: "daily" };
97|  }
98|
99|  // Refunds the day that was charged, even if the job crosses UTC midnight.
100|  return {
101|    ok: true,
102|    reservation: {
103|      amountMicro: args.amountMicro,
104|      day: args.day,
105|      release: async () => {
106|        await releaseDaily();
107|        await releaseTotal();
108|      },
109|      adjust: async (deltaMicro: number) => {
110|        if (deltaMicro === 0) return;
111|        try {
112|          await kv.incrBy(totalKey, deltaMicro);
113|          await kv.incrBy(dayKey, deltaMicro);
114|        } catch {
115|          // Best effort: the reserve already bounds the spend.
116|        }
117|      },
118|    },
119|  };
