1|import "server-only";
2|import { EMOTIONS } from "@/core/types";
3|import type { Chapter, EmotionId, Scene, SceneEmotion, SceneInput } from "@/core/types";
4|import { renormalize8 } from "@/core/emotion";
5|import { validateSceneCoverage } from "@/core/scenes";
6|import { runPool } from "../../pipeline/http";
7|import { classifyScene } from "../../pipeline/classify";
8|import type { ClassifyMetaUsage } from "../../pipeline/classify";
9|import { SCENE_SCHEMA, chapterPrompt, parseScenes } from "../../pipeline/segment";
10|import type { JevClient } from "../../pipeline/jev";
11|import type { MetaClient } from "../../pipeline/meta";
12|import { jevCostUsd, metaCostUsd } from "../../pipeline/prices";
13|import type { UploadUsage } from "./state";
14|
15|// Per-call ceilings inside the 60 s step budget. The pipeline's own retry
16|// policy still applies beneath each timeout; a storm that outlasts the
17|// route just fails the step, and the client re-drives it idempotently.
18|export const META_CALL_TIMEOUT_MS = 20_000;
19|export const JEV_CALL_TIMEOUT_MS = 12_000;
20|
21|export function fetchWithTimeout(fetchFn: typeof fetch, ms: number): typeof fetch {
22|  return (url, init) => fetchFn(url, { ...init, signal: AbortSignal.timeout(ms) });
23|}
24|
25|export class WorkError extends Error {
26|  constructor(public kind: "segment" | "store") {
27|    super(`upload ${kind} failed`);
28|    this.name = "WorkError";
29|  }
30|}
31|
32|function clampSceneText(scene: SceneInput): SceneInput {
33|  return {
34|    start_n: scene.start_n,
35|    end_n: scene.end_n,
36|    title: scene.title.slice(0, 200),
37|    summary: scene.summary.slice(0, 2000),
38|    characters: scene.characters.slice(0, 12).map((c) => c.slice(0, 120)),
39|  };
40|}
41|
42|// One part segments like an Oz chapter: same prompt, same schema, one
43|// retry with the coverage problems pasted back. Throws WorkError when the
44|// output is still invalid, which fails the job with a refund.
45|export async function segmentPart(
46|  meta: MetaClient,
47|  chapter: Pick<Chapter, "ch" | "title" | "start_n" | "end_n">,
48|  paras: { n: number; text: string }[],
49|  usage: UploadUsage,
50|): Promise<SceneInput[]> {
51|  const full = chapter as Chapter;
52|  let problems: string | undefined;
53|  for (let attempt = 0; attempt < 2; attempt++) {
54|    const result = await meta.completeJson({
55|      system: "You split book chapters into scenes for a music soundtrack. Answer with JSON only.",
56|      user: chapterPrompt(full, paras, problems),
57|      schemaName: "chapter_scenes",
58|      schema: SCENE_SCHEMA as unknown as Record<string, unknown>,
59|    });
60|    usage.metaRequests += 1;
61|    usage.metaPrompt += result.promptTokens;
62|    usage.metaCached += result.cachedTokens;
63|    usage.metaCompletion += result.completionTokens;
64|    let inputs: SceneInput[];
65|    try {
66|      inputs = parseScenes(result.data).map(clampSceneText);
67|    } catch (e) {
68|      problems = (e as Error).message;
69|      continue;
70|    }
71|    const found = validateSceneCoverage(full, inputs);
72|    if (found.length === 0) return inputs;
73|    problems = found.map((p) => p.message).join("\n");
74|  }
75|  throw new WorkError("segment");
76|}
77|
78|// Contributor-only emotion for BYOK and for the free path without a Jev
79|// key. Mirrors the override prompt, plus the intensity/tempo questions Jev
80|// would have answered. Only the 8 ids; a bad vector fails the scene.
81|const DIRECT_SCHEMA = {
82|  type: "object",
83|  properties: {
84|    vector: {
85|      type: "object",
86|      properties: Object.fromEntries(EMOTIONS.map((id) => [id, { type: "number" }])),
87|      required: [...EMOTIONS],
88|      additionalProperties: false,
89|    },
90|    intensity: { type: "number" },
91|    tempo: { type: "number" },
92|    reason: { type: "string" },
93|  },
94|  required: ["vector", "intensity", "tempo", "reason"],
95|  additionalProperties: false,
96|};
97|
98|function clamp01(value: unknown): number | null {
99|  if (typeof value !== "number" || !Number.isFinite(value)) return null;
100|  return Math.min(1, Math.max(0, value));
101|}
102|
103|export async function classifySceneDirect(
104|  meta: MetaClient,
105|  scene: Pick<Scene, "title">,
106|  text: string,
107|  usage: UploadUsage,
108|): Promise<SceneEmotion> {
109|  try {
110|    const result = await meta.completeJson({
111|      system: "You score soundtrack mood as a probability mix over 8 feelings. Answer with JSON only.",
112|      user:
113|        `Scene "${scene.title}": ${text}\n` +
114|        "Give a probability mix over the 8 feelings only (calma, alegria, tristeza, suspenso, " +
115|        "misterio, aventura, combate, asombro), plus intensity (0 calm to 1 intense) and tempo " +
116|        "(0 still to 1 urgent), plus one short sentence for reason.",
117|      schemaName: "emotion_direct",
118|      schema: DIRECT_SCHEMA,
119|    });
120|    usage.metaRequests += 1;
121|    usage.metaPrompt += result.promptTokens;
122|    usage.metaCached += result.cachedTokens;
123|    usage.metaCompletion += result.completionTokens;
124|    const parsed = result.data as {
125|      vector?: Partial<Record<EmotionId, number>>;
126|      intensity?: unknown;
127|      tempo?: unknown;
128|      reason?: unknown;
129|    };
130|    const vector = renormalize8(parsed.vector ?? {});
131|    const intensity = clamp01(parsed.intensity);
132|    const tempo = clamp01(parsed.tempo);
133|    if (vector === null || intensity === null || tempo === null) {
134|      return { jev: null, muse_override: null, final: null, error: "direct vector invalid" };
135|    }
136|    const override = { vector, reason: String(parsed.reason ?? "").slice(0, 300), model: meta.model };
137|    return { jev: null, muse_override: override, final: { vector, intensity, tempo }, error: null };
138|  } catch {
139|    return { jev: null, muse_override: null, final: null, error: "direct classify failed" };
140|  }
141|}
142|
143|// Every scene gets an emotion; per-scene failures record the error and
144|// keep final null like Oz, so one bad scene never fails the book.
145|export async function classifyPart(
146|  scenes: (SceneInput & Pick<Scene, "id" | "ch">)[],
147|  texts: string[],
148|  ctx: { bookTitle: string; chapterTitle: string },
149|  deps: { meta: MetaClient; jev: JevClient | null },
150|  usage: UploadUsage,
151|): Promise<SceneEmotion[]> {
152|  const metaUsage: ClassifyMetaUsage = {
153|    model: deps.meta.model,
154|    requests: 0,
155|    promptTokens: 0,
156|    cachedTokens: 0,
157|    completionTokens: 0,
158|    costUsd: 0,
159|  };
160|  const out = await runPool(scenes, 4, async (scene, index) => {
161|    const text = texts[index] ?? "";
162|    if (deps.jev === null) return classifySceneDirect(deps.meta, scene, text, usage);
163|    const emotion = await classifyScene(scene as Scene, text, ctx.bookTitle, ctx.chapterTitle, deps as { jev: JevClient; meta: MetaClient }, metaUsage);
164|    if (emotion.jev) {
165|      usage.jevInput += emotion.jev.input_tokens;
166|      usage.jevOutput += emotion.jev.output_tokens;
167|      usage.jevRequests += 1;
168|    }
169|    return emotion;
170|  });
171|  usage.metaRequests += metaUsage.requests;
172|  usage.metaPrompt += metaUsage.promptTokens;
173|  usage.metaCached += metaUsage.cachedTokens;
174|  usage.metaCompletion += metaUsage.completionTokens;
175|  return out;
176|}
177|
178|export function usageCostMicro(usage: UploadUsage): number {
179|  const usd =
180|    metaCostUsd({ prompt: usage.metaPrompt, cached: usage.metaCached, completion: usage.metaCompletion }) +
181|    jevCostUsd(usage.jevInput);
182|  return Math.round(usd * 1_000_000);
183|}
184|
185|export function usageCostUsd(usage: UploadUsage): number {
186|  return Math.round((usageCostMicro(usage) / 1_000_000) * 1_000_000) / 1_000_000;
187|}

