19|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
20|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
21|
22|// The uploads token is its own private store: the image store is public
23|// and a store's access mode is fixed at creation, so private puts would
24|// fail against it. Never fall back to the public store.
25|const REQUIRED = [
26|  "UPLOADS_BLOB_READ_WRITE_TOKEN",
27|  "META_API_KEY",
28|  "SESSION_SECRET",
29|  "IP_HASH_SALT",
30|] as const;
