1|import "server-only";
2|import { del, get, list, put } from "@vercel/blob";
3|
4|// Private Blob store for uploads: book text belongs to the reader, so
5|// paths carry the unguessable job id, blobs stay private, and only this
6|// server module reads them back. Routes never return Blob URLs. The token
7|// is always explicit: the default env store is the public image store,
8|// which cannot hold private blobs.
9|export interface UploadStore {
10|  saveJson(path: string, json: string): Promise<void>;
11|  readText(path: string): Promise<string | null>;
12|  remove(path: string): Promise<void>;
13|  listAll(prefix: string): Promise<{ pathname: string; uploadedAt: number }[]>;
14|}
15|
16|const BLOB_TIMEOUT_MS = 8_000;
17|
18|export function createUploadStore(token: string): UploadStore {
19|  return {
20|    async saveJson(path: string, json: string): Promise<void> {
21|      await put(path, json, {
22|        access: "private",
23|        addRandomSuffix: false,
24|        allowOverwrite: true,
25|        contentType: "application/json",
26|        token,
27|        abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
28|      });
29|    },
30|    async readText(path: string): Promise<string | null> {
31|      // Null when the path was never written; anything else throws.
32|      const found = await get(path, {
33|        access: "private",
34|        useCache: false,
35|        token,
36|        abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
37|      });
38|      if (!found || found.stream === null) return null;
39|      return await new Response(found.stream).text();
40|    },
41|    async remove(path: string): Promise<void> {
42|      await del(path, { token, abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS) });
43|    },
44|    async listAll(prefix: string): Promise<{ pathname: string; uploadedAt: number }[]> {
45|      const out: { pathname: string; uploadedAt: number }[] = [];
46|      let cursor: string | undefined;
47|      for (;;) {
48|        const page = await list({
49|          prefix,
50|          limit: 1000,
51|          ...(cursor ? { cursor } : {}),
52|          token,
53|          abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
54|        });
55|        for (const blob of page.blobs) out.push({ pathname: blob.pathname, uploadedAt: blob.uploadedAt.getTime() });
56|        if (!page.hasMore) break;
57|        cursor = page.cursor;
58|      }
59|      return out;
60|    },
61|  };
62|}

