1|// Model price table (USD per 1M tokens) and cost helpers. Cached Meta
2|// tokens are part of prompt_tokens and bill at the cached rate.
3|export const PRICES = {
4|  jevInputPer1M: 0.042,
5|  metaInputPer1M: 0.1,
6|  metaCachedPer1M: 0.002,
7|  metaOutputPer1M: 0.2,
8|} as const;
9|
10|export function jevCostUsd(inputTokens: number): number {
11|  return (inputTokens / 1_000_000) * PRICES.jevInputPer1M;
12|}
13|
14|// Standard-mode Muse Spark (no "-contributor" suffix) bills at the
15|// higher Standard rates, the same table as the Modal Shared Endpoint.
16|export function isStandardMuse(model: string | undefined): boolean {
17|  return model !== undefined && model.startsWith("muse-") && !model.endsWith("-contributor");
18|}
19|
20|export function metaCostUsd(input: { prompt: number; cached: number; completion: number }, model?: string): number {
21|  if (isStandardMuse(model)) return modalCostUsd(input);
22|  const fresh = Math.max(0, input.prompt - input.cached);
23|  return (
24|    (fresh / 1_000_000) * PRICES.metaInputPer1M +
25|    (input.cached / 1_000_000) * PRICES.metaCachedPer1M +
26|    (input.completion / 1_000_000) * PRICES.metaOutputPer1M
27|  );
28|}
29|
30|// Muse Spark Open on a Modal Shared Endpoint (per-token, scales to zero).
31|export const MODAL_PRICES = {
32|  modalInputPer1M: 1.25,
33|  modalCachedPer1M: 0.15,
34|  modalOutputPer1M: 4.25,
35|} as const;
36|
37|export function modalCostUsd(input: { prompt: number; cached: number; completion: number }): number {
38|  const fresh = Math.max(0, input.prompt - input.cached);
39|  return (
40|    (fresh / 1_000_000) * MODAL_PRICES.modalInputPer1M +
41|    (input.cached / 1_000_000) * MODAL_PRICES.modalCachedPer1M +
42|    (input.completion / 1_000_000) * MODAL_PRICES.modalOutputPer1M
43|  );
44|}
