1|// Whole-book check: each ready book's prerendered first-scene route ships its text.
2|// Scans the prerendered HTML and RSC files of every scene route for the
3|// scene's own excerpt. Run after `npm run build`. Fails when the scene's
4|// own text is missing from its HTML (which would prove the scan itself
5|// is blind).
6|import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
7|import { dirname, join } from "node:path";
8|import { fileURLToPath } from "node:url";
9|
10|const root = join(dirname(fileURLToPath(import.meta.url)), "..");
11|const EXCERPT_LEN = 80;
12|const MIN_EXCERPT_LEN = 40;
13|
14|export function unescapePayload(text) {
15|  return text
16|    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
17|    .replace(/\\[nrt]/g, "")
18|    .replace(/\\"/g, '"')
19|    .replace(/\\\\/g, "\\")
20|    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
21|    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(Number(dec)))
22|    .replace(/&quot;/g, '"')
23|    .replace(/&amp;/g, "&")
24|    .replace(/&lt;/g, "<")
25|    .replace(/&gt;/g, ">");
26|}
27|
28|// Lowercase alphanumeric only, so JSON/HTML escaping and whitespace
29|// differences cannot hide a leak.
30|export function normalize(text) {
31|  return unescapePayload(text)
32|    .toLowerCase()
33|    .replace(/[^\p{L}\p{N}]+/gu, "");
34|}
35|
36|export function excerpt(text) {
37|  return normalize(text).slice(0, EXCERPT_LEN);
38|}
39|
40|// Only each ready book's first scene is prerendered (the rest render on
41|// demand), so the check scans that one route per book under /read.
42|function loadScenes() {
43|  const library = JSON.parse(readFileSync(join(root, "data/library.json"), "utf8"));
44|  const out = [];
45|  for (const entry of library) {
46|    if (entry.status !== "ready") continue;
47|    const dir = join(root, "data/books", entry.id);
48|    if (!existsSync(join(dir, "analysis.json"))) continue;
49|    const book = JSON.parse(readFileSync(join(dir, "book.json"), "utf8"));
50|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8"));
51|    const first = analysis.scenes[0];
52|    if (!first) continue;
53|    const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
54|    out.push({
55|      id: `${entry.id}/${first.id}`,
56|      texts: Array.from({ length: first.end_n - first.start_n + 1 }, (_, i) => byN.get(first.start_n + i) ?? ""),
57|    });
58|  }
59|  return out;
60|}
61|
62|function routeFiles(routeId) {
63|  const [bookId, sceneId] = routeId.split("/");
64|  const dir = join(root, ".next/server/app/read", bookId);
65|  const names = existsSync(dir) ? readdirSync(dir) : [];
66|  const own = [`${sceneId}.html`, `${sceneId}.rsc`];
67|  const segments = names.filter((n) => n === `${sceneId}.segments`);
68|  const files = [];
69|  for (const name of own) {
70|    const path = join(dir, name);
71|    if (existsSync(path)) files.push(path);
72|  }
73|  for (const seg of segments) {
74|    for (const name of readdirSync(join(dir, seg))) {
75|      const path = join(dir, seg, name);
76|      if (statSync(path).isFile()) files.push(path);
77|    }
78|  }
79|  return files;
80|}
81|
82|export function checkIsolation({ scenes, readFile = (p) => readFileSync(p, "utf8"), filesFor = routeFiles } = {}) {
83|  const list = scenes ?? loadScenes();
84|  const failures = [];
85|  for (let i = 0; i < list.length; i++) {
86|    const scene = list[i];
87|    if (!scene) continue;
88|    const files = filesFor(scene.id);
89|    if (files.length === 0) {
90|      failures.push(`${scene.id}: no prerendered files (run npm run build first)`);
91|      continue;
92|    }
93|    // The scene's own first paragraph must be in the HTML itself, not
94|    // just the RSC payload: otherwise the scan is blind to an empty page.
95|    const html = files.filter((f) => f.endsWith(".html")).map((f) => normalize(readFile(f))).join("\n");
96|    const own = excerpt(scene.texts[0] ?? "");
97|    if (own.length >= MIN_EXCERPT_LEN && !html.includes(own)) {
98|      failures.push(`${scene.id}: own text missing from HTML, the scan is blind`);
99|    }
100|  }
101|  return failures;
102|}
103|
104|if (process.argv[1] === fileURLToPath(import.meta.url)) {
105|  const failures = checkIsolation();
106|  if (failures.length > 0) {
107|    for (const failure of failures) console.error(`isolation: ${failure}`);
108|    process.exit(1);
109|  }
110|  console.log("isolation: every prerendered first-scene route carries its own text");
111|}

