+  const costMicro = usageCostMicro(usage);
+  await settleSpendOnce(args.kv, job, costMicro);
+  job.status = "done";
+  job.usage = usage;
+  job.costMicro = costMicro;
+  await saveUploadJob(args.kv, job);
+  return doneResult(job);
+}

